<?php
namespace App\Livewire;
use App\Models\Student;use App\Models\StudentGuardian;use App\Models\User;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;use Livewire\Attributes\Layout;use Livewire\Component;use Throwable;
#[Layout('layouts.app')] class ParentRegister extends Component {public string $name='',$email='',$phone='',$relationship='Parent',$password='';public array $studentIds=[];public function save():void{abort_unless(Auth::user()->hasPermission('parents.manage'),403);$this->validate(['name'=>['required','string','max:255'],'email'=>['required','email','max:255',Rule::unique('users','email')->where('school_id',Auth::user()->school_id)],'phone'=>['nullable','string','max:50'],'relationship'=>['required','string','max:50'],'password'=>['required','string','min:8'],'studentIds'=>['required','array','min:1'],'studentIds.*'=>['integer',Rule::exists('students','id')]]);try{$schoolId=Auth::user()->school_id;$students=Student::where('school_id',$schoolId)->whereIn('id',$this->studentIds)->get();if($students->count()!==count(array_unique($this->studentIds))){$this->addError('studentIds','A selected learner does not belong to this school.');return;}DB::transaction(function()use($schoolId,$students){$parent=User::create(['school_id'=>$schoolId,'name'=>$this->name,'email'=>$this->email,'phone'=>$this->phone?:null,'password'=>$this->password,'role'=>'parent','employment_status'=>'active']);foreach($students as $student){DB::table('portal_user_students')->insert(['school_id'=>$schoolId,'user_id'=>$parent->id,'student_id'=>$student->id,'relationship'=>$this->relationship,'created_at'=>now(),'updated_at'=>now()]);StudentGuardian::updateOrCreate(['student_id'=>$student->id,'email'=>$this->email],['name'=>$this->name,'relationship'=>$this->relationship,'phone'=>$this->phone?:null,'is_primary'=>!$student->guardians()->exists()]);}});$this->reset(['name','email','phone','password','studentIds']);$this->relationship='Parent';session()->flash('status','Parent account registered and linked to the selected learner(s).');}catch(Throwable $exception){report($exception);$this->addError('save','The parent record was not saved because of a system error.');}}public function render(){return view('livewire.parent-register',['students'=>Student::with('schoolClass')->where('school_id',Auth::user()->school_id)->where('status','active')->orderBy('name')->get(),'pageTitle'=>'Register Parent']);}}
